import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  output: "standalone",
  transpilePackages: ["@smartec/ui"],
};

export default nextConfig;

@import "tailwindcss";
@import "@smartec/ui/styles.css";
@import "./tokens.css";

@source "../../../../packages/ui/src";
@custom-variant dark (&:is(.dark *));

@layer base {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
    border-color: var(--border);
  }

  html {
    min-width: 320px;
    background: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }

  body {
    min-width: 320px;
    min-height: 100vh;
    margin: 0;
    overflow-x: clip;
    background: var(--background);
    color: var(--foreground);
    font-size: var(--text-body);
    line-height: var(--leading-body);
  }

  a {
    color: inherit;
    text-decoration: none;
  }

  button,
  input,
  textarea,
  select {
    font: inherit;
  }

  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 3px;
    box-shadow: var(--focus-ring);
  }

  ::selection {
    background: var(--primary);
    color: var(--primary-foreground);
  }
}

@layer utilities {
  .site-container {
    width: min(
      100% - (2 * var(--site-page-padding)),
      var(--site-container-max)
    );
    margin-inline: auto;
  }

  .site-reading-width {
    max-width: var(--site-reading-max);
  }

  .site-section {
    padding-block: var(--site-section-space);
  }

  .surface-grid {
    background-image:
      linear-gradient(
        to right,
        color-mix(in srgb, var(--border) 42%, transparent) 1px,
        transparent 1px
      ),
      linear-gradient(
        to bottom,
        color-mix(in srgb, var(--border) 42%, transparent) 1px,
        transparent 1px
      );
    background-size: 2rem 2rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

:root {
  color-scheme: light;

  --background: #f8fafc;
  --foreground: #0f172a;
  --card: #ffffff;
  --card-foreground: #0f172a;
  --popover: #ffffff;
  --popover-foreground: #0f172a;
  --primary: #1d4ed8;
  --primary-foreground: #ffffff;
  --secondary: #e0f2fe;
  --secondary-foreground: #0c4a6e;
  --muted: #f1f5f9;
  --muted-foreground: #475569;
  --accent: #dbeafe;
  --accent-foreground: #1e3a8a;
  --destructive: #b91c1c;
  --destructive-foreground: #ffffff;
  --success: #166534;
  --success-foreground: #ffffff;
  --warning: #854d0e;
  --warning-foreground: #ffffff;
  --border: #cbd5e1;
  --input: #cbd5e1;
  --ring: #2563eb;

  --font-family-sans:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  --font-family-mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;

  --text-display: clamp(2.75rem, 6vw, 5.75rem);
  --text-h1: clamp(2.25rem, 4.5vw, 4.25rem);
  --text-h2: clamp(1.875rem, 3.5vw, 3rem);
  --text-h3: clamp(1.375rem, 2.2vw, 1.875rem);
  --text-body-lg: clamp(1.0625rem, 1.3vw, 1.25rem);
  --text-body: 1rem;
  --text-body-sm: 0.875rem;
  --text-label: 0.75rem;

  --leading-display: 0.98;
  --leading-heading: 1.12;
  --leading-body: 1.65;
  --tracking-display: -0.045em;
  --tracking-heading: -0.025em;
  --tracking-label: 0.08em;

  --radius-base: 0.875rem;
  --radius-token-sm: 0.5rem;
  --radius-token-md: 0.875rem;
  --radius-token-lg: 1.25rem;
  --radius-token-xl: 1.75rem;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px rgb(15 23 42 / 6%);
  --shadow-md: 0 12px 30px rgb(15 23 42 / 10%);
  --shadow-lg: 0 28px 80px rgb(15 23 42 / 14%);
  --shadow-primary: 0 18px 48px rgb(29 78 216 / 22%);

  --gradient-hero:
    radial-gradient(circle at 15% 10%, rgb(96 165 250 / 22%), transparent 32%),
    radial-gradient(circle at 88% 18%, rgb(14 165 233 / 16%), transparent 30%),
    linear-gradient(180deg, #ffffff 0%, #f8fafc 58%, #eff6ff 100%);
  --gradient-panel: linear-gradient(145deg, #ffffff 0%, #f1f5f9 100%);

  --duration-fast: 140ms;
  --duration-normal: 240ms;
  --duration-slow: 480ms;
  --ease-standard: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --focus-ring: 0 0 0 0.2rem color-mix(in srgb, var(--ring) 28%, transparent);
}

.dark,
[data-theme="dark"] {
  color-scheme: dark;

  --background: #07111f;
  --foreground: #f8fafc;
  --card: #0b172a;
  --card-foreground: #f8fafc;
  --popover: #0b172a;
  --popover-foreground: #f8fafc;
  --primary: #60a5fa;
  --primary-foreground: #07111f;
  --secondary: #10233d;
  --secondary-foreground: #e0f2fe;
  --muted: #111e31;
  --muted-foreground: #cbd5e1;
  --accent: #172d4c;
  --accent-foreground: #dbeafe;
  --destructive: #f87171;
  --destructive-foreground: #07111f;
  --success: #4ade80;
  --success-foreground: #07111f;
  --warning: #facc15;
  --warning-foreground: #07111f;
  --border: #314158;
  --input: #314158;
  --ring: #60a5fa;

  --shadow-sm: 0 1px 2px rgb(0 0 0 / 25%);
  --shadow-md: 0 14px 34px rgb(0 0 0 / 34%);
  --shadow-lg: 0 32px 90px rgb(0 0 0 / 45%);
  --shadow-primary: 0 18px 48px rgb(96 165 250 / 20%);
  --gradient-hero:
    radial-gradient(circle at 15% 10%, rgb(59 130 246 / 24%), transparent 32%),
    radial-gradient(circle at 88% 18%, rgb(14 165 233 / 18%), transparent 30%),
    linear-gradient(180deg, #07111f 0%, #091525 58%, #0d1b2f 100%);
  --gradient-panel: linear-gradient(145deg, #0b172a 0%, #111e31 100%);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --font-sans: var(--font-family-sans);
  --font-mono: var(--font-family-mono);
  --radius-sm: var(--radius-token-sm);
  --radius-md: var(--radius-token-md);
  --radius-lg: var(--radius-token-lg);
  --radius-xl: var(--radius-token-xl);
}
